<script setup lang="ts">
import SwotParticipationPanel from './SwotParticipationPanel.vue'
import {computed,ref,watch} from 'vue'
import {useAuthStore} from '@/stores/auth'
import {strategyAdminCommand} from '@/services/strategy-admin'
const props=defineProps<{data:any;campaign:any;busy:boolean;initialQuadrant?:string}>(),emit=defineEmits<{command:[fn:()=>Promise<any>]}>(),auth=useAuthStore()
const quadrants:Record<string,string>={strengths:'Forças',weaknesses:'Fraquezas',opportunities:'Oportunidades',threats:'Ameaças'}
const scopes:Record<string,string>={own_team:'Equipa representada',organization:'Organização / Corporativa',other_team:'Outra equipa (proposta opcional)'}
const form=ref({quadrant:props.initialQuadrant||'strengths',contribution_scope:'own_team',team_id:'',thematic_area_id:'',contribution:''}),filter=ref(''),contextFilter=ref(''),reviewReason=ref<Record<string,string>>({}),area=ref<any>(null)
const userId=computed(()=>auth.profile?.id)
const rows=computed(()=>(props.data.swot_contributions||[]).filter((r:any)=>r.campaign_id===props.campaign.id))
const mine=computed(()=>rows.value.filter((r:any)=>r.user_id===userId.value))
const submitted=computed(()=>(props.data.swot_submissions||[]).some((r:any)=>r.campaign_id===props.campaign.id&&r.user_id===userId.value))
const countA=computed(()=>mine.value.filter((r:any)=>r.contribution_scope==='own_team').length),countB=computed(()=>mine.value.length-countA.value)
const today=new Date().toISOString().slice(0,10)
const ownTeams=computed(()=>props.campaign.collection_revision===2?(props.data.swot_participant_contexts||[]).filter((r:any)=>r.campaign_id===props.campaign.id&&r.user_id===userId.value&&r.team_id).map((r:any)=>r.team_id):(props.data.user_assignments||[]).filter((r:any)=>r.user_id===userId.value&&r.active&&(!r.starts_on||r.starts_on.slice(0,10)<=today)&&(!r.ends_on||r.ends_on.slice(0,10)>=today)).map((r:any)=>r.team_id))
const availableTeams=computed(()=>(props.data.teams||[]).filter((t:any)=>t.active&&(form.value.contribution_scope==='own_team'?ownTeams.value.includes(t.id):!ownTeams.value.includes(t.id))))
const areas=computed(()=>(props.data.strategy_thematic_areas||[]).filter((r:any)=>r.active))
const areaName=(id:string)=>props.data.strategy_thematic_areas?.find((a:any)=>a.id===id)?.name||'Sem classificação (registo anterior)'
const teamName=(id:string)=>props.data.teams?.find((t:any)=>t.id===id)?.name||'Organização'
const reviewed=(id:string)=>props.data.swot_context_reviews?.find((r:any)=>r.contribution_id===id)
const isSubmitted=(r:any)=>props.data.swot_submissions?.some((s:any)=>s.campaign_id===r.campaign_id&&s.user_id===r.user_id)
function canReview(r:any){return isSubmitted(r)&&!reviewed(r.id)&&r.contribution_scope!=='own_team'&&props.data.swot_campaign_validators?.some((v:any)=>v.campaign_id===props.campaign.id&&v.user_id===userId.value&&(v.team_id||null)===(r.team_id||null))}
function add(){emit('command',async()=>{await strategyAdminCommand('contribution_add',props.campaign.id,form.value);form.value.contribution=''})}
function submit(){if(confirm('Submeter a participação? Os contributos ficam preservados e seguem para validação.'))emit('command',()=>strategyAdminCommand('participation_submit',props.campaign.id,{}))}
function review(r:any,decision:string){emit('command',()=>strategyAdminCommand('context_review',props.campaign.id,{contribution_id:r.id,decision,reason:reviewReason.value[r.id]}))}
function editArea(r?:any){area.value=r?{...r,team_ids:(props.data.strategy_area_teams||[]).filter((a:any)=>a.area_id===r.id).map((a:any)=>a.team_id)}:{name:'',active:true,team_ids:[]}}
function saveArea(){emit('command',async()=>{await strategyAdminCommand('thematic_area_save',area.value.id||null,area.value);area.value=null})}
watch(()=>form.value.contribution_scope,()=>form.value.team_id='')
watch(()=>props.campaign.id,()=>{form.value.contribution='';filter.value=''})
</script>
<template>
<SwotParticipationPanel v-if="campaign.collection_revision===2" :data="data" :campaign="campaign" :busy="busy" :initial-quadrant="initialQuadrant" @command="fn=>emit('command',fn)"/>
<details v-if="auth.canManageStrategy" class="sq-card p-3 mb-3"><summary>Configurar áreas temáticas e equipas sugeridas</summary><p>As ligações sugerem áreas relevantes. Qualquer equipa pode contribuir numa área transversal.</p><button class="btn btn-outline-primary mb-2" @click="editArea()">Nova área temática</button><div v-for="a in data.strategy_thematic_areas" :key="a.id" class="d-flex gap-2 mb-2"><span>{{a.name}} · {{a.active?'Ativa':'Inativa'}}</span><button class="btn btn-sm btn-outline-primary" @click="editArea(a)">Editar área</button></div><form v-if="area" @submit.prevent="saveArea"><label class="d-block">Nome da área temática<input v-model="area.name" class="form-control" required maxlength="200"></label><label><input v-model="area.active" type="checkbox"> Ativa</label><fieldset><legend class="h6">Equipas sugeridas (opcional)</legend><label v-for="t in data.teams?.filter((t:any)=>t.active)" :key="t.id" class="d-block"><input v-model="area.team_ids" type="checkbox" :value="t.id"> {{t.name}}</label></fieldset><button class="btn btn-primary" :disabled="busy">Guardar área</button><button type="button" class="btn btn-secondary ms-2" @click="area=null">Cancelar</button></form></details>
<section v-if="campaign.status==='open'&&(campaign.collection_revision!==2||(data.swot_participant_contexts||[]).some((r:any)=>r.campaign_id===campaign.id&&r.user_id===userId))" class="sq-card p-3 mb-3"><h2 class="h5">A minha participação</h2><div v-if="campaign.collection_revision!==2" class="row g-2 mb-3"><div class="col-md-6"><div class="border rounded p-3"><strong>A · A minha equipa: {{countA}}</strong><div>Mínimo {{campaign.min_own}} · Máximo {{campaign.max_own}}</div></div></div><div class="col-md-6"><div class="border rounded p-3"><strong>B · Organização e outras equipas: {{countB}}</strong><div>Mínimo {{campaign.min_other}} · Máximo {{campaign.max_other}}</div></div></div></div><p v-if="submitted" class="alert alert-success">Participação submetida. A validação preserva os teus textos originais.</p><template v-else><p>Guarda uma ideia de cada vez com área, quadrante e contexto. Ao terminar, submete a participação. Se não identificares mais ideias relevantes, o coordenador pode concluir com exceção justificada.</p><form @submit.prevent="add"><div class="row g-3"><label class="col-md-6">Contexto<select v-model="form.contribution_scope" class="form-select"><option v-for="(label,key) in scopes" :key="key" :value="key">{{label}}</option></select></label><label v-if="form.contribution_scope!=='organization'" class="col-md-6">Equipa<select v-model="form.team_id" class="form-select" required><option value="">Seleciona a equipa</option><option v-for="t in availableTeams" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label class="col-md-6">Área temática<select v-model="form.thematic_area_id" class="form-select" required><option value="">Seleciona a área</option><option v-for="a in areas" :key="a.id" :value="a.id">{{a.name}}{{data.strategy_area_teams?.some((m:any)=>m.area_id===a.id&&m.team_id===form.team_id)?' · Sugerida para esta equipa':''}}</option></select></label><label class="col-md-6">Quadrante<select v-model="form.quadrant" class="form-select"><option v-for="(label,key) in quadrants" :key="key" :value="key">{{label}}</option></select></label><label class="col-12">Contributo original<textarea v-model="form.contribution" class="form-control" required maxlength="10000"/></label></div><button class="btn btn-primary mt-3" :disabled="busy">Guardar contributo</button></form><button class="btn btn-success mt-3" :disabled="busy" @click="submit">Submeter participação</button></template></section>
<section class="sq-card p-3 mb-3"><h2 class="h5">Recolha e validação por contexto</h2><label class="d-block mb-3">Filtrar por área temática<select v-model="filter" class="form-select"><option value="">Todas as áreas</option><option v-for="a in data.strategy_thematic_areas" :key="a.id" :value="a.id">{{a.name}} · {{rows.filter((r:any)=>r.thematic_area_id===a.id).length}} contributos</option></select></label><label class="d-block mb-3">Filtrar por contexto<select v-model="contextFilter" class="form-select"><option value="">Todos os contextos</option><option v-for="(label,key) in scopes" :key="key" :value="key">{{label}}</option></select></label><div v-for="r in rows.filter((r:any)=>(!filter||r.thematic_area_id===filter)&&(!contextFilter||r.contribution_scope===contextFilter))" :key="r.id" class="border-bottom py-3"><strong>{{areaName(r.thematic_area_id)}} · {{quadrants[r.quadrant]}}</strong><div class="small">{{r.author_label}} · {{new Date(r.created_at).toLocaleString('pt-PT')}} · {{scopes[r.contribution_scope]}} · {{teamName(r.team_id)}}</div><p class="my-2" style="white-space:pre-wrap">{{r.contribution}}</p><small>{{r.item_id?'Publicado na SWOT oficial':!isSubmitted(r)?'Participação por submeter':r.contribution_scope==='own_team'?'Disponível para consolidação':reviewed(r.id)?(reviewed(r.id).decision==='approved'?'Contexto aprovado':'Não aprovado neste contexto'):'Aguarda validação do contexto'}}</small><p v-if="reviewed(r.id)" class="small mb-0">{{reviewed(r.id).reason}}</p><div v-if="canReview(r)&&['open','validation'].includes(campaign.status)" class="mt-2"><label class="d-block">Fundamentação da decisão<input v-model="reviewReason[r.id]" class="form-control" maxlength="2000"></label><button class="btn btn-outline-success mt-2" :disabled="busy" @click="review(r,'approved')">Aprovar contexto</button><button class="btn btn-outline-danger mt-2 ms-2" :disabled="busy" @click="review(r,'rejected')">Não aprovar</button></div></div></section>
</template>
